describe('Data Refresh After Mutation', () => {
  const API_BASE_URL = Cypress.env('API_BASE_URL') || 'http://localhost:3000';
  const TEST_TIMEOUT = 5000;

  beforeEach(() => {
    cy.visit(`${API_BASE_URL}`);
    cy.intercept('GET', '**/api/data', { fixture: 'initial-data.json' }).as('getInitialData');
    cy.intercept('POST', '**/api/data', { fixture: 'mutation-response.json' }).as('mutateData');
    cy.intercept('GET', '**/api/data', { fixture: 'refreshed-data.json' }).as('getRefreshedData');
    cy.wait('@getInitialData');
  });

  it('should automatically refresh data after a successful mutation', () => {
    // Verify initial data is displayed
    cy.get('[data-testid="data-display"]').should('contain', 'Initial Value');
    cy.get('[data-testid="data-count"]').should('have.text', '5');

    // Trigger mutation
    cy.get('[data-testid="mutation-button"]').click();

    // Wait for mutation request
    cy.wait('@mutateData');

    // Verify data refresh is triggered automatically
    cy.wait('@getRefreshedData', { timeout: TEST_TIMEOUT });

    // Verify updated data is displayed
    cy.get('[data-testid="data-display"]').should('contain', 'Updated Value');
    cy.get('[data-testid="data-count"]').should('have.text', '10');
  });

  it('should handle refresh failure gracefully after mutation', () => {
    cy.intercept('POST', '**/api/data', { fixture: 'mutation-response.json' }).as('mutateDataSuccess');
    cy.intercept('GET', '**/api/data', { statusCode: 500, body: { error: 'Server Error' } }).as('getRefreshedDataFail');

    // Verify initial data is displayed
    cy.get('[data-testid="data-display"]').should('contain', 'Initial Value');

    // Trigger mutation
    cy.get('[data-testid="mutation-button"]').click();

    // Wait for mutation request
    cy.wait('@mutateDataSuccess');

    // Wait for failed refresh attempt
    cy.wait('@getRefreshedDataFail', { timeout: TEST_TIMEOUT });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to refresh data');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });

  it('should refresh data multiple times for consecutive mutations', () => {
    cy.get('[data-testid="data-display"]').should('contain', 'Initial Value');

    // First mutation
    cy.get('[data-testid="mutation-button"]').click();
    cy.wait('@mutateData');
    cy.wait('@getRefreshedData');
    cy.get('[data-testid="data-display"]').should('contain', 'Updated Value');

    // Second mutation
    cy.get('[data-testid="mutation-button"]').click();
    cy.wait('@mutateData');
    cy.wait('@getRefreshedData');
    cy.get('[data-testid="data-count"]').should('have.text', '10');
  });

  it('should not display stale data during refresh', () => {
    cy.get('[data-testid="data-display"]').should('contain', 'Initial Value');

    // Trigger mutation
    cy.get('[data-testid="mutation-button"]').click();
    cy.wait('@mutateData');

    // Verify loading state appears during refresh
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Wait for refresh to complete
    cy.wait('@getRefreshedData');

    // Verify loading state is gone and new data is displayed
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="data-display"]').should('contain', 'Updated Value');
  });
});
